import { enhanceSelects, selectOverlay, SearchableSelect, normalizeFilter } from './components/selects.js';
import { BottomSheet } from './components/bottom-sheet.js';
import{load,db,roles,access,modules,visible,allowed,editable,save,reset,log,storageProblem}from'./store.js';
import{esc,icon,note,empty,link}from'./components/ui.js';import{home,profile,messages}from'./pages/home.js';import{list,quotes,boundaries}from'./pages/lists.js';import{detail,editor}from'./pages/detail.js';
const app=document.querySelector('#app');let module='home',id='',query='',filter='全部',media={photos:[],signature:'',receipt:null,quoteLines:[]},drawing=false,dirty=false;
export function toast(t){document.querySelector('#toast').textContent=t;document.querySelector('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>document.querySelector('#toast').classList.remove('show'),3500);}
function route(){const parts=location.hash.replace(/^#\/?/,'').split('/');return [parts[0]||'home',decodeURIComponent(parts[1]||'')];}
function ticket(){return visible().find(t=>t.id===id);}
function canRoute(m){return m==='edit'?access[db.role].includes('tasks'):allowed(m);}
// UI context is separate from the unchanged business Mock store.
let background={hash:'#/home',module:'home',query:'',filter:'全部',scroll:0};
let views={};
let formOrigin='', formFromDetail=false, displayedHash=location.hash||'#/home', canGoBack=false;
try { const ui=JSON.parse(sessionStorage.getItem('ec_mobile_sheet_context')); if(ui?.background)background=ui.background;formOrigin=ui?.formOrigin||'';views=ui?.views||{}; } catch {}
formFromDetail=Boolean(history.state?.ecFormOrigin);
const sheet=new BottomSheet({onClose:closeDetail});
const pageTitle=m=>modules[m]?.[0]||({home:'流動工作台',edit:'現場作業',me:'個人中心',messages:'消息'})[m]||'工作台';
function remember(){try{sessionStorage.setItem('ec_mobile_sheet_context',JSON.stringify({background,formOrigin,views}));}catch{}}
function saveView(){if(!id&&module!=='edit'){views[db.role+':'+module]={query,filter,scroll:window.scrollY};remember();}}
function mainBody(m){if(!canRoute(m))return note('此身份沒有此頁面的權限。請使用下方工作入口。');if(m==='home')return home();if(m==='me')return profile();if(m==='messages')return messages();if(m==='quotes')return quotes('',query);if(['materials','finance','tender','warehouse'].includes(m))return boundaries(m);return list(m,query,filter);}
function shell(m,body){const nav=[['home','工作台','home'],[access[db.role][0],db.role==='MASTER'?'任務':'業務','task'],[db.role==='TL'?'approvals':access[db.role].includes('reports')?'reports':'messages',db.role==='TL'?'待辦':access[db.role].includes('reports')?'單據':'消息','file'],['me','我的','user']];
app.innerHTML=`<div class="phone-shell"><header>${m!=='home'?`<a href="${m==='edit'?formOrigin||'#/tasks/'+id:'#/home'}" aria-label="返回">${icon('back')}</a>`:`<img src="../assets/ecinfo-official.svg" alt="EC InfoTech">`}<span class="header-title">${pageTitle(m)}</span><a class="bell" href="#/messages" aria-label="消息">${icon('bell')}${db.messages.some(m=>!m.read)?'<b></b>':''}</a></header><div class="review-strip"><span>評審原型 · 隔離 Mock</span><button type="button" data-ui="roles" class="role-select-trigger" role="combobox" aria-label="切換評審身份" aria-expanded="false" aria-haspopup="listbox">${esc(roles[db.role][0])} ⇄</button></div><main>${storageProblem?note(storageProblem):''}${body}</main><nav aria-label="底部導航">${nav.map(([k,l,i])=>`<a href="#/${k}" class="${m===k?'active':''}">${icon(i)}<span>${l}</span></a>`).join('')}</nav></div>`;}
function render(){selectOverlay.close(false);const oldScroll=sheet.active?sheet.body.scrollTop:0;sheet.hide();[module,id]=route();displayedHash=location.hash||'#/home';
if(module==='edit'){if(!formOrigin.endsWith('/'+id))formOrigin='#/tasks/'+id;const t=ticket();shell('edit',canRoute(module)&&t&&editable(t)?editor(t):note('此工單目前不可編輯；只允許師傅填寫本人進行中的工作。'));if(t&&canRoute(module)&&editable(t))bindEditor(t);enhancePickers();return;}
if(!id){shell(module,mainBody(module));enhancePickers();return;}
if(!allowed(background.module)||background.module==='edit')background={hash:'#/'+module,module,query:'',filter:'全部',scroll:0};
const savedQuery=query,savedFilter=filter;query=background.query;filter=background.filter;shell(background.module,mainBody(background.module));query=savedQuery;filter=savedFilter;window.scrollTo(0,background.scroll);
let body;if(!canRoute(module))body=note('此身份沒有此頁面的權限。');else if(module==='quotes')body=id.startsWith('request-')?requestDetail(Number(id.slice(8))):quotes(id);else if(module==='messages')body=messageDetail(Number(id));else if(['materials','finance','tender','warehouse'].includes(module))body=boundaries(module,id);else{const t=ticket();body=t?detail(t,module):empty('此記錄不在你的工作範圍');}
sheet.open({title:pageTitle(module)+'詳情',html:body,kind:module==='approvals'?'approval':module==='dispatch'?'form':'detail'});
const action=sheet.body.querySelector('.actionbar');if(action){sheet.footer.replaceChildren(...action.childNodes);sheet.footer.hidden=false;action.remove();}else{const quick=[...sheet.body.querySelectorAll('[data-action=call-note],[data-action=call-quote],[data-action=dispatch]')];if(quick.length){sheet.footer.replaceChildren(...quick);sheet.footer.hidden=false;}}
sheet.body.scrollTop=oldScroll;enhancePickers();}
function closeDetail(){if(id&&module!=='edit'){if(canGoBack){canGoBack=false;history.back();}else{history.replaceState(null,'',background.hash);query=background.query;filter=background.filter;render();window.scrollTo(0,background.scroll);}}else sheet.hide();}
async function navigate(){const target=location.hash||'#/home';if(target===displayedHash)return;saveView();if(selectOverlay.popup){selectOverlay.close();history.replaceState(null,'',displayedHash);canGoBack=false;return;}
if(sheet.pending){history.replaceState(null,'',displayedHash);sheet.answer('stay');return;}
if(sheet.frames.length){history.replaceState(null,'',displayedHash);canGoBack=false;await sheet.back();return;}
if(module==='edit'&&dirty){history.replaceState(null,'',displayedHash);const answer=await sheet.ask('離開現場表單？','有未儲存內容，可儲存草稿再返回，或放棄本次修改。',[['save','儲存草稿並離開'],['leave','放棄修改'],['stay','繼續編輯']]);if(answer==='stay')return;if(answer==='save'&&!stash()){toast(storageProblem||'草稿未能儲存');return;}dirty=false;history.replaceState(null,'',target);}
else if(sheet.active&&sheet.dirty){history.replaceState(null,'',displayedHash);if(!await sheet.mayLeave())return;history.replaceState(null,'',target);}
const [next,nextId]=route();if(next==='edit'){formFromDetail=Boolean(id&&module!=='edit');formOrigin=displayedHash;history.replaceState({ecFormOrigin:formOrigin},'',target);remember();}
else if(nextId&&module!=='edit'&&!id){background={hash:displayedHash,module,query,filter,scroll:window.scrollY};canGoBack=true;remember();}
else if(!nextId){const v=views[db.role+':'+next];query=target===background.hash?background.query:v?.query||'';filter=target===background.hash?background.filter:v?.filter||'全部';}
const closedHash=displayedHash;dirty=false;render();if(!nextId&&target===background.hash){window.scrollTo(0,background.scroll);document.querySelector(`a[href="${CSS.escape(closedHash)}"]`)?.focus({preventScroll:true});}else if(next==='edit'||!nextId)window.scrollTo(0,views[db.role+':'+next]?.scroll||0);}
function requestDetail(i){const r=db.quoteRequests[i];return r?`<section class="panel"><h3>${esc(r.ticketId)}</h3><p>${esc(r.text)}</p>${note('公共報價待辦（演示），正式接手與版本操作保留 PC。')}</section>`:empty('找不到報價需求');}
function messageDetail(i){const m=db.messages[i];return m?`<section class="panel"><p>${esc(m.text)}</p><p>${m.read?'已讀':'未讀'}</p><div class="actionbar"><button type="button" class="primary" data-read="${i}">標記已讀</button></div></section>`:empty('找不到消息');}
function enhancePickers(){enhanceSelects();}
function switchRole(role){saveView();sheet.hide();db.role=role;save();background={hash:'#/home',module:'home',query:'',filter:'全部',scroll:0};remember();history.replaceState(null,'','#/home');render();window.scrollTo(0,0);}
async function showRoles(anchor){if(module==='edit'&&dirty){const a=await sheet.ask('切換身份前處理草稿','目前現場表單尚未儲存。',[['save','儲存草稿'],['leave','放棄修改'],['stay','繼續編輯']]);if(a==='stay')return;if(a==='save'&&!stash())return toast(storageProblem);dirty=false;}
new SearchableSelect({anchor,label:'評審身份',value:db.role,options:Object.entries(roles).map(([key,value])=>({value:key,label:value[0]+' · '+value[1]})),onChange:switchRole}).open();}
function collect(){const f=document.querySelector('#reportForm');return {...Object.fromEntries(new FormData(f)),...media};}
function stash(){if(module==='edit'&&document.querySelector('#reportForm')){db.drafts[id]=structuredClone(collect());return save();}return false;}
function mediaRender(){document.querySelector('#photos').innerHTML=media.photos.map((p,i)=>`<div><img src="${p.url}" alt="${esc(p.name)}"><button type="button" data-remove-photo="${i}" aria-label="移除照片 ${i+1}">×</button><small>${esc(p.name)}</small></div>`).join('');document.querySelector('#receiptPreview').innerHTML=media.receipt?`<p>${esc(media.receipt.name)} ${'<button type="button" data-action="remove-receipt">移除收據</button>'}</p>`:'';document.querySelector('#quoteLines').innerHTML=media.quoteLines.map((l,i)=>`<fieldset><legend>報價需求 ${i+1}</legend>${[['name','名稱'],['model','型號'],['location','位置']].map(([k,n])=>`<label>${n}<input data-line="${i}" data-key="${k}" value="${esc(l[k])}"></label>`).join('')}<button type="button" data-remove-line="${i}">移除此項</button></fieldset>`).join('');}
function bindEditor(t){const d=db.drafts[t.id]||t.report||{};media=structuredClone({photos:d.photos||[],signature:d.signature||'',receipt:d.receipt||null,quoteLines:d.quoteLines||[]});mediaRender();const c=document.querySelector('#signature'),ctx=c.getContext('2d');ctx.strokeStyle='#122d45';ctx.lineWidth=3;ctx.lineCap='round';if(media.signature){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,c.width,c.height);img.src=media.signature;}c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);const r=c.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);});c.addEventListener('pointermove',e=>{if(!drawing)return;const r=c.getBoundingClientRect();ctx.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);ctx.stroke();media.signature=c.toDataURL();dirty=true;});c.addEventListener('pointerup',()=>{drawing=false;});c.addEventListener('pointercancel',()=>drawing=false);
document.querySelector('#reportForm').addEventListener('submit',e=>{e.preventDefault();if(!editable(t))return toast('沒有提交權限');const d=collect();let err='';if(!d.serviceDate)err='請填寫服務日期。';else if(!d.srSystems)err='請選擇系統。';else if(!d.srObjectives)err='請選擇工作目的。';else if(!d.completedWork.trim()||!d.faultResult.trim()||!d.signedBy.trim())err='請填妥工作內容、跟進事項及簽署人。';else if(!d.needQuote)err='請選擇是否需要報價。';else if(t.reportKind==='CP'&&!String(d.cpNo||'').trim())err='請填寫 CP 編號。';else if(!media.signature)err='請由客戶在簽名框手寫簽署。';else if(t.reportKind==='CP'&&['Before','After','CP正本'].some(k=>!d.photos.some(p=>p.kind===k)))err='CP 需附 Before、After 及已簽 CP 正本照片（演示可加入各類示例）。';else if(d.transportMode==='Taxi'&&!media.receipt)err='Taxi 車資必須附上收據。';else if(d.needQuote==='yes'&&(!d.quoteLines.length||d.quoteLines.some(l=>!l.name.trim()||!l.model.trim()||!l.location.trim())))err='需報價時，請填妥每項名稱、型號及位置。';if(err){document.querySelector('#formError').textContent=err;document.querySelector('#formError').scrollIntoView({block:'center'});return;}t.report=structuredClone(d);Object.assign(t,{completedWork:d.completedWork,faultResult:d.faultResult,transportFee:Number(d.transportFee||0),beforeServicePhotos:d.photos.filter(p=>p.kind==='Before').map(p=>p.url),afterServicePhotos:d.photos.filter(p=>p.kind==='After').map(p=>p.url)});if(t.reportKind==='CP'){t.cpNo=d.cpNo;t.cpCompletionDate=d.serviceDate;t.cpSignature=d.signature;t.cpSourceImage=d.photos.find(p=>p.kind==='CP正本').url;t.cpStatus='已提交';t.cpSubmittedAt=new Date().toISOString();}else{t.srSystems=[d.srSystems];t.srObjectives=[d.srObjectives];t.signature=d.signature;}t.submitted=true;t.status='待完工確認';if(d.needQuote==='yes')db.quoteRequests.push({ticketId:t.id,text:d.quoteLines.map(l=>`${l.name}／${l.model}／${l.location}`).join('；')});delete db.drafts[t.id];dirty=false;log(t,`${t.reportKind} 已提交，待完工確認${d.needQuote==='yes'?'；需報價已轉公共待辦':''}`);if(formFromDetail&&history.state?.ecFormOrigin===formOrigin){history.back();}else if(formOrigin){history.replaceState(null,'',formOrigin);render();}else location.hash=`#/tasks/${t.id}`;toast(storageProblem||'已儲存提交記錄（本機演示）');});}
async function readPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('只接受 JPEG、PNG 或 WebP 圖片');if(file.size>2*1024*1024)throw Error('圖片大於 2MB，請選較小圖片');return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(Error('無法讀取圖片，請重新選取'));r.onload=()=>resolve({name:file.name,url:r.result});r.readAsDataURL(file);});}
document.addEventListener('input',e=>{if(e.target.closest('.select-popover')||e.target.dataset.filterField)return;if(e.target.id==='search'){query=e.target.value;saveView();const pos=e.target.selectionStart;render();const s=document.querySelector('#search');s.focus();s.setSelectionRange(pos,pos);}else if(module==='edit'){const err=document.querySelector('#formError');if(err)err.textContent='';dirty=true;if(e.target.dataset.line!==undefined)media.quoteLines[e.target.dataset.line][e.target.dataset.key]=e.target.value;}});
document.addEventListener('change',async e=>{if(e.target.dataset.filterField){filter={...normalizeFilter(filter),[e.target.dataset.filterField]:e.target.value};saveView();render();return;}if(['photoInput','receiptInput'].includes(e.target.id)){try{for(const file of e.target.files){if(e.target.id==='photoInput'&&media.photos.length>=4)throw Error('最多可加入 4 張照片');const photo=await readPhoto(file);if(e.target.id==='photoInput'){photo.kind=document.querySelector('#photoKind').value;photo.name=photo.kind+' · '+photo.name;}if(e.target.id==='receiptInput')media.receipt=photo;else media.photos.push(photo);}dirty=true;mediaRender();}catch(err){toast(err.message);}finally{e.target.value='';}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const t=ticket();if(b.dataset.read!==undefined){db.messages[b.dataset.read].read=true;save();sheet.dirty=false;render();return;}if(b.dataset.removePhoto!==undefined){media.photos.splice(Number(b.dataset.removePhoto),1);dirty=true;mediaRender();return;}if(b.dataset.removeLine!==undefined){media.quoteLines.splice(Number(b.dataset.removeLine),1);dirty=true;mediaRender();return;}const a=b.dataset.action;if(!a)return;
if(['accept','arrive','confirm','dispatch','call-quote'].includes(a)&&!b.dataset.approved){const answer=await sheet.ask('確認操作',b.textContent.trim()+'？',[['leave','確認'],['stay','取消']]);if(answer==='leave'){b.dataset.approved='yes';b.click();}return;}delete b.dataset.approved;
if(a==='reset'){if(await sheet.ask('重設手機演示資料？','將清除手機演示草稿、照片與操作記錄，PC 資料不受影響。',[['leave','確認重設'],['stay','取消']])==='leave'){reset();dirty=false;location.hash='#/home';render();toast('手機演示資料已重設');}return;}
if(a==='draft'){toast(stash()?'草稿已儲存在本機':storageProblem||'草稿未能儲存');dirty=false;return;}
if(a==='sample-photo'){if(media.photos.length>=4)return toast('最多 4 張照片');const c=document.createElement('canvas');c.width=480;c.height=320;const x=c.getContext('2d');x.fillStyle='#edf6fc';x.fillRect(0,0,480,320);x.fillStyle='#122d45';x.fillRect(140,50,200,180);x.fillStyle='#2990d0';x.fillRect(160,70,160,100);x.fillStyle='#fff';x.font='22px sans-serif';x.fillText('EC · 示範設備',165,125);x.fillStyle='#122d45';x.fillText('模擬照片 · 非真實現場',100,280);media.photos.push({kind:document.querySelector('#photoKind').value,name:document.querySelector('#photoKind').value+' · 模擬照片',url:c.toDataURL('image/png')});dirty=true;mediaRender();return;}
if(a==='clear-sign'){document.querySelector('#signature').getContext('2d').clearRect(0,0,640,280);media.signature='';dirty=true;return;}if(a==='remove-receipt'){media.receipt=null;dirty=true;mediaRender();return;}if(a==='add-line'){media.quoteLines.push({name:'',model:'',location:''});dirty=true;mediaRender();return;}
if(!t||!canRoute(module))return toast('沒有操作權限');
if(a==='accept'&&db.role==='MASTER'&&t.master===roles.MASTER[1]&&t.status==='待確認'){t.status='待處理';log(t,'已接單，等待出發');}
else if(a==='arrive'&&editable(t)&&t.status==='待處理'){t.arrivedAt=new Date().toISOString();t.status='處理中';log(t,'已記錄到場時間');}
else if(a==='dispatch'&&['TL','CR'].includes(db.role)&&t.phaseReady&&t.status==='待分派'){const date=document.querySelector('#schedule').value;if(!date)return toast('請選擇預約時間');t.schedule=date;t.master=document.querySelector('#master').value;t.status='待確認';log(t,`安排 ${t.master}，${date.replace('T',' ')}；演示階段供料前提`);}
else if(a==='confirm'&&db.role==='TL'&&t.tl===roles.TL[1]&&t.submitted&&t.status==='待完工確認'){t.status='已完成';t.confirmedBy=roles[db.role][1];t.confirmedAt=new Date().toISOString();log(t,'主管確認本次工作完成。'+(document.querySelector('#confirmNote').value||''));}
else if(['call-note','call-quote'].includes(a)&&['CS','CR','TL'].includes(db.role)){let text=document.querySelector('#callNote').value.trim();if(!text)return toast('請先填寫跟進內容');if(a==='call-quote')db.quoteRequests.push({ticketId:t.id,text});log(t,(a==='call-quote'?'CALL 需報價已轉公共待辦：':'CALL 跟進：')+text);}
else return toast('此狀態或身份不可執行操作');sheet.dirty=false;render();toast(storageProblem||'已更新本機演示記錄');});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.message!==undefined)location.hash='#/messages/'+b.dataset.message;if(b.dataset.ui==='roles')showRoles(b);if(b.dataset.ui==='clear-filters'){filter='全部';saveView();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sheet.active&&module==='edit')location.hash=formOrigin||'#/tasks/'+id;});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(module==='edit'&&a?.getAttribute('href')===formOrigin&&history.state?.ecFormOrigin===formOrigin){e.preventDefault();history.back();}},true);
window.addEventListener('hashchange',navigate);window.addEventListener('beforeunload',e=>{if(dirty){stash();e.preventDefault();e.returnValue='';}else if(sheet.active&&sheet.dirty){e.preventDefault();e.returnValue='';}});
try{await load();const v=views[db.role+':'+route()[0]];if(!route()[1]&&v){query=v.query;filter=v.filter;}render();if(!route()[1]&&v)window.scrollTo(0,v.scroll||0);}catch(err){app.innerHTML=`<main>${note('工作台資料未能載入，請檢查 HTTP 服務後重試。')}<button class="primary" id="retry">重新載入</button></main>`;document.querySelector('#retry').onclick=()=>location.reload();}
